package com.aistock.market.marketrefs;
import com.aistock.common.*;import com.aistock.common.marketrefs.*;import com.aistock.common.marketrefs.MarketReferenceRecords.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.http.HttpStatus;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
class MarketVersionReferenceTest {
 static final String V="11111111-1111-1111-1111-111111111111";static final Instant NOW=Instant.parse("2026-10-28T00:00:00Z");
 OwnerResult owner(String id){return new OwnerResult(id,V,NOW,"COMPLETE",null,List.of(new Group("rows","记录","COMPLETE","0",null)));}
 @Test void checksLocalOwnershipBeforeAnyRemoteRequest(){var repo=mock(MarketVersionReferenceRepository.class);var client=mock(MarketVersionReferenceClient.class);when(repo.meta(anyString(),anyString(),any())).thenThrow(new BusinessException("MARKET_ADMIN_RESOURCE_NOT_FOUND","不存在",HttpStatus.NOT_FOUND));assertThrows(BusinessException.class,()->new MarketVersionReferenceService(repo,client,Clock.fixed(NOW,ZoneOffset.UTC)).inspect("SH600030",V));verifyNoInteractions(client);}
 @Test void retainsSuccessfulOwnersButDoesNotTreatWrongOwnerAsZero(){var repo=mock(MarketVersionReferenceRepository.class);var client=mock(MarketVersionReferenceClient.class);when(repo.meta("SH600030",V,NOW)).thenReturn(new VersionMeta("SH600030",V,"baostock","RAW","AVAILABLE",true,NOW));for(String id:List.of("prediction","scheduler","notification"))when(client.read(id,V)).thenReturn(owner(id));var service=new MarketVersionReferenceService(repo,client,Clock.fixed(NOW,ZoneOffset.UTC));assertEquals("COMPLETE",service.inspect("SH600030",V).state());when(client.read("scheduler",V)).thenReturn(owner("prediction"));var partial=service.inspect("SH600030",V);assertEquals("PARTIAL",partial.state());assertEquals("UNKNOWN",partial.owners().get(1).state());assertTrue(partial.owners().get(1).groups().isEmpty());assertEquals("0",partial.owners().get(0).groups().get(0).rows());}
}
